{
  "judgements": [
    {
      "claim_id": "cl-38a36814f417",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["period"],
      "reason": "公司自述2020年海外市场经营情况，给出东南亚、南亚占出口总量46%的具体数字，属实质经营表述；但原文未明确写出'2020年'字样（仅'2020年持续深耕'），期间要素以年份形式出现，故period不视为缺失，实际缺owner。"
    },
    {
      "claim_id": "cl-1bec75795132",
      "is_substantive": false,
      "is_template": false,
      "missing_elements": ["object", "period", "metric", "result", "owner"],
      "reason": "这是报表附注中的口径说明（'注：……'），交代销售量统计口径，不是公司干了什么的经营表述，属数据来源/口径标注类。"
    },
    {
      "claim_id": "cl-357a9d3a4ff9",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["owner"],
      "reason": "公司自述2019年出口钢铁产品362.1万吨并引出分渠道销售情况，有对象（出口钢铁产品）、期间（2019年）、指标（出口量）、结果（362.1万吨），属实质经营表述。"
    },
    {
      "claim_id": "cl-abffdfc96d23",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["period", "metric", "result"],
      "reason": "公司自述截至2015年底持有某子公司100%股权、注册资本21.1亿元及经营范围，是对公司持股与子公司情况的实质陈述；期间以'截至2015年底'给出，故period不缺失，缺的是经营指标与结果。"
    },
    {
      "claim_id": "cl-893f40b4d4ce",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["period", "metric", "result"],
      "reason": "公司自述截至2015年底持有某子公司95.8%股权、注册资本6.2亿元及经营范围，属对公司持股与子公司情况的实质陈述；期间已由'截至2015年底'给出。"
    },
    {
      "claim_id": "cl-506eef4158da",
      "is_substantive": false,
      "is_template": false,
      "missing_elements": ["object", "period", "metric", "result", "owner"],
      "reason": "引用'据钢联资讯'对2016年钢铁表观消费量与粗钢产量的行业预测，说的是行业而非这家公司，属一般行业综述/数据来源标注。"
    },
    {
      "claim_id": "cl-1f97d63f1711",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["metric", "result"],
      "reason": "公司自述2024年通过配合政府部门及宝武集团内产量优化调控实现钢产能有效发挥，有对象（钢产能）、期间（2024年）、责任主体（公司），属实质经营表述；但'有效发挥'无具体指标与量化结果。"
    },
    {
      "claim_id": "cl-4af5757f952e",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["owner"],
      "reason": "公司自述2015年营业总收入较计划减少298.46亿元并拆解普碳钢、钢铁贸易等影响金额及原因，有对象、期间、指标、结果，属实质经营表述。"
    }
  ]
}
